(()=>{const parts=location.pathname.split('/').filter(Boolean),isAr=parts[0]==='ar',base=isAr?'/'+(parts.slice(1).join('/')||'')+(parts.length>1?'/':'') : location.pathname;const route=base==='//'?'/' : base;const to=p=>'/ar'+(p==='/'?'/' : p);const nav=[['الرئيسية','/'],['الأسعار','/pricing/'],['الموزع','/reseller/'],['التطبيقات','/apps/'],['الأدلة','/guides/'],['المدونة','/blog/'],['اتصل بنا','/contact/']];const shell=c=>`<header class="top"><div class="wrap topin"><a class="brand" href="${to('/')}"><img src="/assets/tivione.webp" alt="Tivione IPTV">Tivione IPTV</a><button class="mobile">☰</button><nav class="nav">${nav.map(([n,p])=>`<a href="${to(p)}">${n}</a>`).join('')}<a class="button" href="${to('/pricing/')}">ابدأ الآن</a><select class="language"><option value="en">English</option><option value="fr">Français</option><option value="es">Español</option><option value="ar" selected>العربية</option></select></nav></div></header><main>${c}</main><footer class="footer"><div class="wrap footergrid"><div><strong>Tivione IPTV</strong><p>خطط مشاهدة، أدلة إعداد، وأدوات احترافية للموزعين.</p></div><div><strong>استكشف</strong>${nav.slice(1).map(([n,p])=>`<a href="${to(p)}">${n}</a>`).join('')}</div><div><strong>تواصل</strong><p>واتساب +212 670-779271</p><p>support@reselleriptv.com</p></div></div></footer>`;const head=(e,h,p)=>`<section class="pagehead"><div class="wrap"><span class="eyebrow">${e}</span><h1>${h}</h1><p class="lead">${p}</p></div></section>`;const button=p=>`<a class="button" href="${to(p)}">اكتشف المزيد</a>`;const plans=()=>`<section><div class="wrap"><div class="head"><span class="eyebrow">خطط واضحة</span><h2>اختر مدة الاشتراك المناسبة</h2><p class="muted">جميع الخطط تتضمن الإعداد على الأجهزة المتوافقة ودليل البرامج الإلكتروني.</p></div><div class="grid five">${[['شهر واحد','19'],['3 أشهر','29'],['6 أشهر','39'],['12 شهراً','65'],['24 شهراً','99']].map(([n,p])=>`<article class="card"><h3>${n}</h3><div class="price">€${p}</div><ul class="list"><li>قنوات مباشرة ودليل برامج عالمي</li><li>أفلام ومسلسلات</li><li>أجهزة ومشغلات متوافقة</li><li>مساعدة في الإعداد</li></ul><a class="button" href="${to('/contact/')}">اطلب هذه الخطة</a></article>`).join('')}</div></div></section>`;const home=`<section class="hero"><div class="wrap"><span class="eyebrow">شبكة Tivione IPTV العالمية</span><h1>شاشتك.<br>وقتك.<br>Tivione IPTV.</h1><p class="lead">بث ثابت ومسارات عالمية محسنة ودليل إعداد واضح للأجهزة التي تستخدمها يومياً.</p><div class="actions">${button('/pricing/')} ${button('/reseller/')}</div><div class="chips"><span class="chip">قنوات مباشرة ودليل برامج</span><span class="chip">رياضة وأحداث مباشرة</span><span class="chip">أفلام ومسلسلات</span></div></div></section>${plans()}`;const reseller=`${head('موزع Tivione IPTV','باقات الموزعين','ابدأ وأدر وطوّر عملك عبر أرصدة مرنة وأدوات احترافية.')}<section><div class="wrap grid three">${['تفعيل فوري','أكثر من 22,000 قناة','أكثر من 88,000 فيلم ومسلسل','0.1 رصيد = شهر واحد','0.3 رصيد = 3 أشهر','0.5 رصيد = 6 أشهر','1 رصيد = 12 شهراً','دعم على مدار الساعة','وصول كامل لواجهة API','دعم النطاق الخاص'].map(x=>`<article class="card"><h3>${x}</h3><p>خدمة احترافية لدعم سير عمل الموزع.</p></article>`).join('')}</div></section>`;const apps=`${head('التطبيقات','التطبيقات والتثبيت','اختر مشغلاً متوافقاً واتبع خطوات الإعداد لجهازك.')}<section><div class="wrap grid three">${['IBO Player Pro','Smart STB','IPTV Smarters','TiviMate','Wave','Purple Player'].map(x=>`<article class="card"><h3>${x}</h3><p>مشغل متوافق للاستخدام على الأجهزة المدعومة.</p>${button('/guides/')}</article>`).join('')}</div></section>`;const guides=`${head('أدلة الإعداد','جهّز جهازك','اختر نوع جهازك ثم اتبع خطوات المشغل المناسبة.')}<section><div class="wrap grid three">${['فايرستيك','تلفاز ذكي','أندرويد','آيفون وآيباد','ويندوز','MAG وEnigma2'].map(x=>`<article class="card"><h3>${x}</h3><p>ثبّت مشغلاً متوافقاً وأدخل بيانات الحساب بعد التفعيل.</p>${button('/apps/')}</article>`).join('')}</div></section>`;const blog=`${head('مدونة Tivione IPTV','أدلة الإعداد والبث','مقالات عملية لاختيار المشغلات وتحسين الاستقرار.')}<section><div class="wrap grid three">${['دليل الإعداد للمبتدئين','اختيار مشغل IPTV المناسب','إعداد فايرستيك','تحسين استقرار البث','دليل TiviMate','شرح دليل البرامج الإلكتروني'].map(x=>`<article class="card"><h3>${x}</h3><p>خطوات واضحة للأجهزة والمشغلات والشبكة المنزلية.</p>${button('/guides/')}</article>`).join('')}</div></section>`;const contact=`${head('اتصل بنا','تواصل مع فريق Tivione IPTV','للاستفسارات حول الخطط والإعداد وباقات الموزعين.')}<section><div class="wrap grid three"><article class="card"><h3>واتساب</h3><p>+212 670-779271</p></article><article class="card"><h3>تيليغرام</h3><p>@premiumiptvpanelscom</p></article><article class="card"><h3>البريد الإلكتروني</h3><p>support@reselleriptv.com</p></article></div></section>`;if(isAr){document.documentElement.lang='ar';document.documentElement.dir='rtl';let c=home;if(route==='/pricing/')c=head('الاشتراكات','خطط Tivione IPTV','اختر المدة المناسبة لك.')+plans();else if(route==='/reseller/')c=reseller;else if(route==='/apps/')c=apps;else if(route==='/guides/')c=guides;else if(route==='/blog/')c=blog;else if(route==='/contact/')c=contact;else if(['/privacy/','/refund/','/terms/','/about/'].includes(route))c=head('معلومات Tivione IPTV',route==='/about/'?'عن Tivione IPTV':'سياسة وشروط الخدمة','معلومات واضحة للزوار والعملاء.')+'<section><article class="wrap article"><p>نقدم معلومات واضحة عن الخدمة والدعم وسياسات الاستخدام. استخدم صفحة الاتصال لأي سؤال.</p></article></section>';document.querySelector('#app').innerHTML=shell(c);document.title='Tivione IPTV | العربية';document.querySelector('.language').onchange=e=>{location.href=e.target.value==='ar'?to(route):route};document.querySelector('.mobile').onclick=()=>document.querySelector('.nav').classList.toggle('open')}})();
